import{_ as a,a as t,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 46 Hobbies","description":"学习 would rather 与 prefer 的补语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 46 Hobbies","description":"学习 would rather 与 prefer 的补语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 would rather 与 prefer 的补语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 45 Of men and galaxies","link":"/life/english/new-concept/book-4/unit-06/lesson-045"},"next":{"text":"第四册：流利英语 · Lesson 47 The great escape","link":"/life/english/new-concept/book-4/unit-06/lesson-047"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 45 Of men and galaxies","link":"/life/english/new-concept/book-4/unit-06/lesson-045"},"next":{"text":"第四册：流利英语 · Lesson 47 The great escape","link":"/life/english/new-concept/book-4/unit-06/lesson-047"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-06/lesson-046.md","filePath":"life/english/new-concept/book-4/unit-06/lesson-046.md"}'),n={name:"life/english/new-concept/book-4/unit-06/lesson-046.md"};function i(l,e,s,h,d,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-46-hobbies" tabindex="-1">第四册：流利英语 · Lesson 46 Hobbies <a class="header-anchor" href="#第四册-流利英语-·-lesson-46-hobbies" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 46 Hobbies&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元 6</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕工作之外的兴趣阅读个人议论，区分放松、熟练、社交和身份认同等不同目的。不要假设所有人都应把爱好变成成绩或收入；学习说明某项活动对某个人的具体作用。重点使用 would rather 与 prefer 比较选择，并保持后接动词形式正确。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>hobby</td><td>/ˈhɒbi/</td><td>n.</td><td>爱好</td><td>take up a hobby</td></tr><tr><td>leisure</td><td>/ˈleʒə/</td><td>n.</td><td>闲暇</td><td>leisure time</td></tr><tr><td>craft</td><td>/krɑːft/</td><td>n.</td><td>手艺</td><td>learn a craft</td></tr><tr><td>satisfaction</td><td>/ˌsætɪsˈfækʃən/</td><td>n.</td><td>满足感</td><td>personal satisfaction</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take up — 开始从事一种爱好</li><li>for its own sake — 为事情本身的价值</li></ul><h2 id="语法讲解-would-rather-与-prefer-的补语" tabindex="-1">语法讲解：would rather 与 prefer 的补语 <a class="header-anchor" href="#语法讲解-would-rather-与-prefer-的补语" aria-label="Permalink to &quot;语法讲解：would rather 与 prefer 的补语&quot;">​</a></h2><p>would rather + 动词原形表示宁愿做某事；would rather A than B 中两个动词保持原形。prefer doing A to doing B 使用介词 to，不是比较连词 than。prefer to do A rather than do B 也是常见形式。would rather 后若另有主语，常用过去式表达现在或未来偏好，如 I would rather you came tomorrow；这不是叙述过去已经来过。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I would rather repair an old radio than buy another one.</p></blockquote><p>我宁愿修理一台旧收音机，也不愿再买一台。</p><p>would rather 后 repair 与 than 后 buy 都是动词原形；another one 指另一台 radio。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>prefer repairing than buying 错把两套搭配混合；应写 prefer repairing to buying。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对比朗读 rather repair than buy 与 prefer repairing to buying；听清两套结构的动词形式差异。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I would rather make a small wooden box than watch another series. Measuring and shaping the pieces requires my full attention. I enjoy the activity for its own sake, even when the result is imperfect.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句介绍一种不以成绩为目的的爱好，包含偏好、过程和个人价值。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>选择结构引入爱好，具体过程说明体验，让步句保留不完美作品的价值。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：She prefers drawing ___ collecting stamps.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> prefer doing A to doing B。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>改错：I would rather to stay at home.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I would rather stay at home.</p><p><strong>解析：</strong> would rather 后接动词原形。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>示例中 another one 的 one 代替什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> radio</p><p><strong>解析：</strong> 同类可数名词的替代词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：would rather 与 prefer 的补语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-045">上一课</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-06/lesson-047">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(n,[["render",i]]);export{u as __pageData,b as default};
